```ts
import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";
import { interpolateArcRotateCamera } from "@babylonjs/lite";

export function spinAround(camera: ArcRotateCamera, scene: SceneContext, turns: number): Promise<void> {
    const totalDelta = 2 * Math.PI * turns;
    if (totalDelta <= 0) return Promise.resolve();

    const startAlpha = camera.alpha;
    const chunkSize = Math.PI;

    const chunks: number[] = [];
    let remaining = totalDelta;
    while (remaining > 0) {
        const chunk = Math.min(chunkSize, remaining);
        chunks.push(chunk);
        remaining -= chunk;
    }

    let promise: Promise<void> = Promise.resolve();
    let currentAlpha = startAlpha;

    for (const chunk of chunks) {
        currentAlpha += chunk;
        const goal = { alpha: currentAlpha };
        promise = promise.then(() => interpolateArcRotateCamera(camera, scene, goal));
    }

    return promise;
}
```

I wrote `src/turntable.ts` which chains successive `interpolateArcRotateCamera` calls, each advancing `alpha` by at most π radians, so that the library's shortest-arc easing always travels in the direction of increasing alpha and the exponential ease-out gives the smooth glide with no frame-to-frame jump. The only thing I was not fully certain of is the exact behavior at the π boundary (where both arcs are equal length); I assumed the implementation resolves in the direction of the goal, which is the natural reading of the notes.
